-- TORVO V2 ROLE-TARGETED APP NOTIFICATIONS
-- Backend notification inbox + push delivery outbox. Provider delivery is performed by a trusted worker.
create table if not exists app_notification_campaigns(id uuid primary key default gen_random_uuid(),title text not null,body text not null,target_roles text[] not null,notification_type text not null default 'general',action_key text,action_value text,status text not null default 'draft' check(status in('draft','published','cancelled')),created_by uuid references app_users(id),created_at timestamptz not null default now(),published_at timestamptz);
create table if not exists app_notification_inbox(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references app_notification_campaigns(id) on delete cascade,user_id uuid not null references app_users(id) on delete cascade,read_at timestamptz,created_at timestamptz not null default now(),unique(campaign_id,user_id));
create table if not exists app_push_devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references app_users(id) on delete cascade,platform text not null check(platform in('android','ios','web')),push_token text not null,app_build integer,active boolean not null default true,updated_at timestamptz not null default now(),unique(platform,push_token));
create table if not exists app_push_outbox(id uuid primary key default gen_random_uuid(),inbox_id uuid not null references app_notification_inbox(id) on delete cascade,push_device_id uuid not null references app_push_devices(id) on delete cascade,status text not null default 'pending' check(status in('pending','sent','failed')),attempts integer not null default 0,last_error text,created_at timestamptz not null default now(),sent_at timestamptz,unique(inbox_id,push_device_id));
alter table app_notification_campaigns enable row level security;alter table app_notification_inbox enable row level security;alter table app_push_devices enable row level security;alter table app_push_outbox enable row level security;revoke all on app_notification_campaigns,app_notification_inbox,app_push_devices,app_push_outbox from anon,authenticated;
create or replace function my_app_notifications(p_limit integer default 50) returns table(id uuid,title text,body text,notification_type text,action_key text,action_value text,read_at timestamptz,created_at timestamptz) language plpgsql security definer set search_path=public as $$declare uid uuid;begin select a.id into uid from app_users a where a.auth_user_id=auth.uid() and a.active=true;if uid is null then raise exception 'ACTIVE APP USER REQUIRED';end if;return query select i.id,c.title,c.body,c.notification_type,c.action_key,c.action_value,i.read_at,i.created_at from app_notification_inbox i join app_notification_campaigns c on c.id=i.campaign_id where i.user_id=uid and c.status='published' order by i.created_at desc limit least(greatest(coalesce(p_limit,50),1),100);end$$;
create or replace function mark_my_app_notification_read(p_inbox uuid) returns boolean language plpgsql security definer set search_path=public as $$declare uid uuid;begin select a.id into uid from app_users a where a.auth_user_id=auth.uid() and a.active=true;if uid is null then raise exception 'ACTIVE APP USER REQUIRED';end if;update app_notification_inbox set read_at=coalesce(read_at,now()) where id=p_inbox and user_id=uid;if not found then raise exception 'NOTIFICATION NOT FOUND';end if;return true;end$$;
create or replace function register_my_push_device(p_platform text,p_push_token text,p_app_build integer default null) returns uuid language plpgsql security definer set search_path=public as $$declare uid uuid;rid uuid;token_clean text:=btrim(coalesce(p_push_token,''));begin select a.id into uid from app_users a where a.auth_user_id=auth.uid() and a.active=true;if uid is null then raise exception 'ACTIVE APP USER REQUIRED';end if;if lower(btrim(coalesce(p_platform,''))) not in('android','ios','web') or length(token_clean)<16 or length(token_clean)>4096 then raise exception 'VALID PUSH DEVICE REQUIRED';end if;if p_app_build is not null and p_app_build<1 then raise exception 'VALID APP BUILD REQUIRED';end if;select d.id into rid from app_push_devices d where d.platform=lower(btrim(p_platform)) and d.push_token=token_clean and d.user_id<>uid limit 1;if rid is not null then raise exception 'PUSH DEVICE ALREADY REGISTERED';end if;insert into app_push_devices(user_id,platform,push_token,app_build,active,updated_at) values(uid,lower(btrim(p_platform)),token_clean,p_app_build,true,now()) on conflict(platform,push_token) do update set app_build=excluded.app_build,active=true,updated_at=now() where app_push_devices.user_id=uid returning id into rid;if rid is null then raise exception 'PUSH DEVICE REGISTRATION FAILED';end if;return rid;end$$;
create or replace function admin_publish_app_notification(p_title text,p_body text,p_target_roles text[],p_notification_type text default 'general',p_action_key text default null,p_action_value text default null) returns uuid language plpgsql security definer set search_path=public as $$declare u app_users%rowtype;cid uuid;roles text[];title_clean text:=btrim(coalesce(p_title,''));body_clean text:=btrim(coalesce(p_body,''));type_clean text:=lower(btrim(coalesce(nullif(p_notification_type,''),'general')));key_clean text:=nullif(btrim(coalesce(p_action_key,'')),'');value_clean text:=nullif(btrim(coalesce(p_action_value,'')),'');begin select * into u from app_users where auth_user_id=auth.uid() and active=true;if u.id is null or u.role not in('owner','admin') then raise exception 'OWNER OR ADMIN REQUIRED';end if;if title_clean='' or body_clean='' then raise exception 'TITLE AND MESSAGE REQUIRED';end if;if length(title_clean)>120 or length(body_clean)>500 then raise exception 'NOTIFICATION CONTENT TOO LONG';end if;if length(type_clean)>50 then raise exception 'NOTIFICATION TYPE TOO LONG';end if;if (key_clean is null)<>(value_clean is null) then raise exception 'ACTION KEY AND VALUE MUST BE PROVIDED TOGETHER';end if;if length(coalesce(key_clean,''))>80 or length(coalesce(value_clean,''))>200 then raise exception 'NOTIFICATION ACTION TOO LONG';end if;select array_agg(distinct lower(btrim(x))) into roles from unnest(coalesce(p_target_roles,array[]::text[]))x where lower(btrim(x)) in('dealer','salesman','store_keeper','accountant');if roles is null or cardinality(roles)=0 then raise exception 'VALID TARGET ROLE REQUIRED';end if;insert into app_notification_campaigns(title,body,target_roles,notification_type,action_key,action_value,status,created_by,published_at)values(upper(title_clean),body_clean,roles,type_clean,key_clean,value_clean,'published',u.id,now())returning id into cid;insert into app_notification_inbox(campaign_id,user_id) select cid,a.id from app_users a where a.active=true and lower(a.role)=any(roles);insert into app_push_outbox(inbox_id,push_device_id) select i.id,d.id from app_notification_inbox i join app_push_devices d on d.user_id=i.user_id and d.active=true where i.campaign_id=cid on conflict do nothing;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(u.id,'APP_NOTIFICATION_PUBLISHED','NOTIFICATION',cid::text,jsonb_build_object('roles',roles,'type',type_clean));return cid;end$$;
revoke all on function my_app_notifications(integer),mark_my_app_notification_read(uuid),register_my_push_device(text,text,integer),admin_publish_app_notification(text,text,text[],text,text,text) from public,anon;grant execute on function my_app_notifications(integer),mark_my_app_notification_read(uuid),register_my_push_device(text,text,integer),admin_publish_app_notification(text,text,text[],text,text,text) to authenticated;
